package ch.bbw.zork;/* * author:  Michael Kolling, Version: 1.0, Date: July 1999 * refactoring: Rinaldo Lanza, September 2020 */import ch.bbw.zork.Items.Item;import ch.bbw.zork.Items.Key;import ch.bbw.zork.enums.Direction;import ch.bbw.zork.interfaces.Uncover;import java.io.BufferedReader;import java.io.IOException;import java.io.InputStream;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.HashMap;import java.util.InputMismatchException;import static ch.bbw.zork.Constants.*;public class Parser {	private InputStream inputStream;    private Player player;    private HashMap<Integer, Item> loadedItemList;    private HashMap<Integer, Furniture> loadedFurnitureList;	public Parser(InputStream inputStream) {		this.inputStream = inputStream;	}	public String[] getCommandInputs() {		BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));		try {			String inputLine = bufferedReader.readLine();			String[] tokens = inputLine.split(" ");			if (tokens.length > 2) {				throw new InputMismatchException("At most 1 Argument is expected.");			}			else if (!Zork2.validCommands.contains(tokens[0])) {				throw new IllegalArgumentException(String.format("'%s' is not a valid command!", tokens[0]));			}			return tokens;		} catch (Exception exc) {			System.out.println("There was an error during reading: " + exc.getMessage());		}		return null;	}    public static void clearScreen() {        System.out.print("\033[H\033[2J");        System.out.flush();    }    public static String padLeft(String text, char ch, int width) {        if (text.length() >= width) {            return text;        }        StringBuilder sb = new StringBuilder();        while (sb.length() < width - text.length()) {            sb.append(ch);        }        sb.append(text);        return sb.toString();    }    public String promptInput(String prompt) {        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));        String input = "";        while (input.isEmpty()) {            try {                System.out.print(prompt);                input = bufferedReader.readLine();            } catch (IOException exc) {                System.out.println("You cannot have no name!");            }        }        return input;    }    public void waitForInput() {        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));        try {            System.out.print("> ");            String input = bufferedReader.readLine();            processCommand(input.split(" "));        } catch (Exception e) {            System.out.println(e.getMessage());        }    }    public int chooseOption(String prompt, String[] options) {        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(this.inputStream));        int optionCount = options.length;        for (int i = 0; i < optionCount; i++) {            System.out.println((i + 1) + ". " + options[i]);        }        while (true) {            try {                System.out.print(prompt);                String input = bufferedReader.readLine();                int choice = Integer.parseInt(input);                if (choice > optionCount || choice < 0) {                    throw new InputMismatchException("Invalid choice.");                }                return choice;            }            catch (InputMismatchException e) {                System.out.println("Invalid choice. Please enter a number between 0 and " + optionCount);            }            catch(Exception exc) {                System.out.println("There was an error during reading: " + exc.getMessage());            }        }    }    public void processCommand(String[] inputs) {        switch (inputs[0]) {            case "move":                this.move(inputs[1]);                break;            case "scan":                this.scan();                break;            case "check":                this.check(Integer.parseInt(inputs[1]));                break;            case "take":                this.take(inputs[1]);                break;            case "drop":                this.drop(inputs[1]);                break;            case "stash":                this.stash(inputs[1]);                break;            case "fetch":                this.fetch(inputs[1]);                break;            case "help":                this.help();                break;            case "quit":                this.quit();                break;            default:                throw new InputMismatchException("Invalid command.");        }    }    private void move(String direction) {        Direction dir = Direction.parse(direction);        Room currentRoom = Game.getHouse().getPlayerLocation();        Door door = currentRoom.getDoor(dir);        if (door.isLocked()) {            Player player = Game.getPlayer();            ArrayList<Key> keys = player.getAvailableKeys();            if (keys.isEmpty()) {                System.out.println("You do not have any keys to open this door!");            }            else {                for (Key key : keys) {                    if (door.tryUnlock(key)) {                        System.out.println("You unlocked the door!");                        break;                    }                }                if (door.isLocked()) {                    System.out.println("Non of your keys match this lock");                }            }        }        if (!door.isLocked()) {            System.out.println("You open the door and walk through.");            door.getRoom(dir).enter();        }        Game.addTime(-MOVE_TIME);    }    private void scan() {        System.out.println("You look around and see:");        ArrayList<Furniture> furnitureList = Game.getHouse().getPlayerLocation().getFurnitureList();        Player player = Game.getPlayer();        Room currentRoom = Game.getHouse().getPlayerLocation();        HashMap<Integer, Furniture> scannedList = currentRoom.getScannedList();        int i = 1;        for (Furniture furniture : furnitureList) {            if (furniture.getIsUncovered()) {                System.out.printf("%s: %s", i, furniture.getName());                scannedList.put(i, furniture);                i++;            }            else {                for (Uncover uncover : player.getAllUncovers()) {                    if (furniture.tryUncover(uncover.getUncoverID())) {                        System.out.printf("%s: %s", i, furniture.getName());                        scannedList.put(i, furniture);                        i++;                        break;                    }                }            }        }        currentRoom.setScannedList(scannedList);        setLoadedFurnitureList(scannedList);        Game.addTime(-SCAN_TIME);    }    private void check(int scanID) {        Room currentRoom = Game.getHouse().getPlayerLocation();        Furniture furniture = currentRoom.getScannedList().get(scanID);        if (furniture == null) {            System.out.println("There is no furniture with id " + scanID);        }        else {            furniture.check();        }        Game.addTime(-CHECK_TIME);    }    private void take(String item) {    }    private void drop(String item) {    }    private void stash(String item) {    }    private void fetch(String item) {    }    private void help() {    }    private void quit() {    }    public Player getPlayer() {        return player;    }    public void setPlayer(Player player) {        this.player = player;    }    public HashMap<Integer, Item> getLoadedItemList() {        return loadedItemList;    }    public void setLoadedItemList(HashMap<Integer, Item> loadedItemList) {        this.loadedItemList = loadedItemList;    }    public HashMap<Integer, Furniture> getLoadedFurnitureList() {        return loadedFurnitureList;    }    public void setLoadedFurnitureList(HashMap<Integer, Furniture> loadedFurnitureList) {        this.loadedFurnitureList = loadedFurnitureList;    }}